"INSERT INTO job_sources (city, organization_id, employer_name, kind, config, location_terms, search_text, notes) SELECT 'philadelphia', organization_id, employer_name, kind, CASE WHEN kind='phenom' THEN json_set(config, '$.state', 'Pennsylvania') ELSE config END, 'Philadelphia, King of Prussia, Conshohocken, Malvern, Wayne, Radnor, Plymouth Meeting, Blue Bell, Horsham, Fort Washington, Wilmington, Newark DE, Cherry Hill, Camden, Mount Laurel, Princeton', 'security', 'Second city row added at the Philadelphia launch' FROM job_sources WHERE (lower(employer_name)=lower('Comcast') OR organization_id=(SELECT id FROM organizations WHERE slug='comcast')) AND NOT EXISTS (SELECT 1 FROM job_sources j2 WHERE j2.city='philadelphia' AND (lower(j2.employer_name)=lower('Comcast') OR j2.employer_name=job_sources.employer_name)) ORDER BY id LIMIT 1;",
